create extension if not exists pgcrypto; create table if not exists public.commitments (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade not null, title text not null, owner text not null default 'You', due_at timestamptz, status text not null default 'needs_confirmation', source text, confidence numeric, created_at timestamptz not null default now(), completed_at timestamptz); create table if not exists public.commitment_events (id uuid primary key default gen_random_uuid(), commitment_id uuid references public.commitments(id) on delete cascade not null, user_id uuid references auth.users(id) on delete cascade not null, event_type text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now()); alter table public.commitments enable row level security; alter table public.commitment_events enable row level security; create policy "users manage own commitments" on public.commitments for all using (auth.uid()=user_id) with check (auth.uid()=user_id); create policy "users manage own events" on public.commitment_events for all using (auth.uid()=user_id) with check (auth.uid()=user_id);